// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [formData, setFormData] = useState({
    userName: "",
    birthday: "",
  });

  // 初始化頂部 Hero 文字 (不需要傳圖片網址了，因為我們要直接在下方塞 video)
  useEffect(() => {
    setHeroData({
      imageUrl: "", // 清空，改由我們自己控制影片
      title: "您好，我是乳房外科小幫手",
      description: "請填寫基本資料，再按下開始。",
    });
  }, [setHeroData]);

  // 點擊影片區域切換播放/暫停
  const handleToggleVideo = () => {
    if (!videoRef.current) return;
    if (isPlaying) {
      videoRef.current.pause();
      setIsPlaying(false);
    } else {
      videoRef.current
        .play()
        .then(() => setIsPlaying(true))
        .catch((err) => console.log("影片播放受阻：", err));
    }
  };

  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }

    if (videoRef.current) {
      videoRef.current.pause();
    }

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));

    navigate("/selection");
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className={styles.homeContainer}>
      {/* 沉浸式大畫面視訊講解區 (替代原本的靜態圖片) */}
      <div className={styles.heroVideoContainer} onClick={handleToggleVideo}>
        <video
          ref={videoRef}
          src="/assets/eve_sdm_talk.mp4"
          playsInline
          className={styles.heroVideo}
          onEnded={() => setIsPlaying(false)}
        />

        {/* 暫停時顯示的浮動播放提示，像你上傳的畫面那樣乾淨 */}
        {!isPlaying && (
          <div className={styles.videoOverlay}>
            <div className={styles.playIconButton}>▶</div>
            <p className={styles.playHintText}>點擊聆聽小幫手引言導覽</p>
          </div>
        )}
      </div>

      {/* 下方原本的表單輸入區 */}
      <div className={styles.inputWrapper}>
        <Input
          label="請輸入您的姓名"
          name="userName"
          placeholder="請輸入您的姓名"
          value={formData.userName}
          onChange={handleInputChange}
        />

        <Input
          label="請輸入您的出生年月日"
          type="date"
          name="birthday"
          value={formData.birthday}
          onChange={handleInputChange}
        />
      </div>

      {/* 下方原本的按鈕區域 */}
      <div className={styles.buttonWrapper}>
        <Button onClick={handleStart} fullWidth>
          開始
        </Button>
      </div>
    </div>
  );
};

export default Home;
